mapper.select:
SELECT id,task_num,type,task_detail,task_address,site_route,principal,created_user,end_time,create_time,status,deal_method,evaluate, deal_result,move_stack_target_siteroute,move_stack_target_name,target_siteid FROM tb_task
AND task_num like concat(concat('%', #{taskDto.taskNum}), '%')
AND site_route like concat(concat('%',#{taskDto.siteRoute}),'%')
AND status = #{taskDto.status}
AND type = #{taskDto.type}
AND principal = #{taskDto.principal}
AND end_time <= STR_TO_DATE(#{taskDto.endTime}, '%Y-%m-%d %H:%i:%s')
AND end_time >= STR_TO_DATE(#{taskDto.endStartTime}, '%Y-%m-%d %H:%i:%s')
ORDER BY create_time DESC

mapper.update:
UPDATE tb_task
deal_method = #{taskDto.dealMethod}, deal_result = #{taskDto.dealResult}, principal = #{taskDto.principal}, status = #{taskDto.status}, finish_time = NOW()
WHERE id = #{taskDto.id}

UPDATE tb_task
evaluate = #{taskDto.evaluate}, evaluate_user = #{taskDto.evaluateUser}, evaluate_time = STR_TO_DATE(#{taskDto.evaluateTime}, '%Y-%m-%d %H:%i:%s')
WHERE id = #{taskDto.id}

